#!/bin/sh
# Generated by ~/rog-tune/rog-tune.sh: run ReGreet inside sway on the AMD GPU (the NVIDIA card stays asleep).
# Wait for the AMD driver first. Started before it, sway opens the early boot framebuffer, which vanishes when the driver takes over:
# the greeter keeps running and accepting keys on a screen that shows only the old boot messages.
drv() { basename "$(readlink "$1/device/driver" 2>/dev/null)"; }
card=
i=0
while [ "$i" -lt 150 ] && [ -z "$card" ]; do
	for c in /sys/class/drm/card[0-9]; do
		if [ "$(drv "$c")" = amdgpu ] && ls -d "$c"-eDP-* >/dev/null 2>&1; then card=$c; break; fi
	done
	[ -n "$card" ] || { sleep 0.1; i=$((i + 1)); }
done
# 15 s without the AMD driver means it failed: only then is the boot framebuffer safe to use, and it keeps a login screen on the panel
if [ -z "$card" ]; then
	for c in /sys/class/drm/card[0-9]; do
		if [ "$(drv "$c")" = simple-framebuffer ]; then card=$c; break; fi
	done
fi
[ -n "$card" ] || exit 1
WLR_DRM_DEVICES=/dev/dri/$(basename "$card")
export WLR_DRM_DEVICES
export XCURSOR_SIZE=32
exec sway -c /etc/greetd/sway.conf
